/**
 * @module views/dashboard/GeneratedWorldModal
 * Modal viewer on Story Overview for inspecting the structured world generated by "Build a world from a pitch".
 */

import React, { useEffect } from 'react';
import { Globe, X } from '@/components/icons';
import type { DashboardStory } from './types';

export interface GeneratedWorldModalProps {
    isOpen: boolean;
    generatedWorld: DashboardStory['generated_world'];
    onClose: () => void;
}

export const GeneratedWorldModal: React.FC<GeneratedWorldModalProps> = ({
    isOpen,
    generatedWorld,
    onClose
}) => {
    useEffect(() => {
        if (!isOpen) return;
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [isOpen, onClose]);

    if (!isOpen || !generatedWorld?.draft) return null;

    const { pitch, size, createdAt, draft } = generatedWorld;
    const regions = draft.land?.regions || [];
    const places = draft.land?.places || [];
    const peoples = draft.powers?.peoples || [];
    const factions = draft.powers?.factions || [];
    const history = draft.past?.history || [];
    const rules = draft.past?.rules || [];

    return (
        <div
            className="fixed inset-0 z-50 bg-stone-900/50 backdrop-blur-xs flex items-center justify-center p-4 animate-fade-in"
            role="dialog"
            aria-modal="true"
            aria-labelledby="generated-world-modal-title"
            onClick={(e) => {
                if (e.target === e.currentTarget) onClose();
            }}
        >
            <div className="bg-surface border border-edge-strong rounded-2xl shadow-2xl w-full max-w-3xl max-h-[85vh] flex flex-col overflow-hidden">
                <div className="p-5 border-b border-edge flex items-center justify-between gap-4 bg-card">
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="p-2 rounded-xl bg-gold-tint border border-gold-edge text-gold-ink shrink-0">
                            <Globe size={18} />
                        </div>
                        <div className="min-w-0">
                            <h3
                                id="generated-world-modal-title"
                                className="text-lg font-bold font-serif text-ink-900 truncate"
                            >
                                Generated World
                            </h3>
                            <p className="text-xs text-ink-500">
                                Size: {size}
                                {createdAt ? ` · Built ${new Date(createdAt).toLocaleDateString()}` : ''}
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 rounded-xl text-ink-500 hover:text-ink-900 hover:bg-wash transition-colors cursor-pointer"
                        aria-label="Close generated world viewer"
                    >
                        <X size={18} />
                    </button>
                </div>

                <div className="p-5 overflow-y-auto space-y-6 text-sm text-ink-800">
                    {pitch && (
                        <div className="bg-inset border border-edge-soft rounded-xl p-4 space-y-1">
                            <div className="text-[11px] font-mono uppercase tracking-wider text-ink-500 font-bold">
                                Pitch
                            </div>
                            <p className="text-sm text-ink-900 leading-relaxed">{pitch}</p>
                        </div>
                    )}

                    {(regions.length > 0 || places.length > 0) && (
                        <section className="space-y-3">
                            <h4 className="text-sm font-bold font-serif text-ink-900 border-b border-edge-soft pb-1.5">
                                The Land
                            </h4>
                            {regions.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-xs font-mono uppercase tracking-wider text-ink-500 font-bold">
                                        Regions ({regions.length})
                                    </div>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                                        {regions.map((region) => (
                                            <div key={region.name} className="p-3 rounded-xl bg-inset border border-edge-soft">
                                                <div className="font-bold text-xs text-ink-900">{region.name}</div>
                                                <p className="text-xs text-ink-600 mt-1 leading-relaxed">{region.summary}</p>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                            {places.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-xs font-mono uppercase tracking-wider text-ink-500 font-bold">
                                        Places ({places.length})
                                    </div>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                                        {places.map((place) => (
                                            <div key={place.name} className="p-3 rounded-xl bg-inset border border-edge-soft">
                                                <div className="font-bold text-xs text-ink-900">{place.name}</div>
                                                <div className="text-[11px] text-ink-500">
                                                    {place.kind} · {place.region}
                                                </div>
                                                <p className="text-xs text-ink-600 mt-1 leading-relaxed">{place.summary}</p>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </section>
                    )}

                    {(peoples.length > 0 || factions.length > 0) && (
                        <section className="space-y-3">
                            <h4 className="text-sm font-bold font-serif text-ink-900 border-b border-edge-soft pb-1.5">
                                Peoples &amp; Factions
                            </h4>
                            {peoples.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-xs font-mono uppercase tracking-wider text-ink-500 font-bold">
                                        Peoples ({peoples.length})
                                    </div>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                                        {peoples.map((people) => (
                                            <div key={people.name} className="p-3 rounded-xl bg-inset border border-edge-soft">
                                                <div className="font-bold text-xs text-ink-900">{people.name}</div>
                                                <p className="text-xs text-ink-600 mt-1 leading-relaxed">{people.summary}</p>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                            {factions.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-xs font-mono uppercase tracking-wider text-ink-500 font-bold">
                                        Factions ({factions.length})
                                    </div>
                                    <div className="space-y-2">
                                        {factions.map((faction) => (
                                            <div key={faction.name} className="p-3 rounded-xl bg-inset border border-edge-soft space-y-1">
                                                <div className="font-bold text-xs text-ink-900">{faction.name}</div>
                                                <p className="text-xs text-ink-700 leading-relaxed">{faction.goal}</p>
                                                <div className="text-[11px] text-ink-500 flex flex-wrap gap-x-3 gap-y-0.5">
                                                    {faction.holds.length > 0 && <span>Holds: {faction.holds.join(', ')}</span>}
                                                    {faction.rivals.length > 0 && <span>Rivals: {faction.rivals.join(', ')}</span>}
                                                    {faction.allies.length > 0 && <span>Allies: {faction.allies.join(', ')}</span>}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </section>
                    )}

                    {(history.length > 0 || rules.length > 0) && (
                        <section className="space-y-3">
                            <h4 className="text-sm font-bold font-serif text-ink-900 border-b border-edge-soft pb-1.5">
                                History &amp; Rules
                            </h4>
                            {history.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-xs font-mono uppercase tracking-wider text-ink-500 font-bold">
                                        History ({history.length})
                                    </div>
                                    <ul className="space-y-1.5">
                                        {history.map((entry, idx) => (
                                            <li key={`${entry.when}-${idx}`} className="p-3 rounded-xl bg-inset border border-edge-soft text-xs">
                                                <span className="font-bold text-ink-900">{entry.when}:</span>{' '}
                                                <span className="text-ink-700">{entry.event}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                            {rules.length > 0 && (
                                <div className="space-y-2">
                                    <div className="text-xs font-mono uppercase tracking-wider text-ink-500 font-bold">
                                        Rules of the World ({rules.length})
                                    </div>
                                    <ul className="space-y-1.5">
                                        {rules.map((rule) => (
                                            <li key={rule.name} className="p-3 rounded-xl bg-inset border border-edge-soft text-xs">
                                                <span className="font-bold text-ink-900">{rule.name}:</span>{' '}
                                                <span className="text-ink-700">{rule.rule}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                        </section>
                    )}
                </div>
            </div>
        </div>
    );
};
